toad_implementation.code_blueprint:
canvas {
  size: 960px 540px;
  fill: #09111E;
  font-family: "Inter, sans-serif";
}

>monitorBg = #09111E;
>ekgGreen = #10B981;
>spo2Cyan = #00E5FF;
>panelBg = #111C2E;
>textMuted = #64748B;
>textWhite = #F8FAFC;

rect #vitalCardHeart {
  at: top left of canvas offset 32px 32px;
  size: 432px 220px;
  fill: >panelBg;
  stroke: >ekgGreen;
  stroke-width: 1px;
  radius: 8px;
}

text #hrLabel {
  at: top left of #vitalCardHeart offset 20px 16px;
  content: "HEART RATE // ECG LEAD II";
  font-size: 12px;
  font-weight: 700;
  color: >ekgGreen;
}

text #hrValue {
  at: below #hrLabel offset 8px;
  content: "72";
  font-size: 64px;
  font-weight: 800;
  color: >ekgGreen;
}

text #hrUnit {
  at: right of #hrValue offset 16px;
  content: "BPM";
  font-size: 16px;
  font-weight: 600;
  color: >textMuted;
}

rect #vitalCardSpo2 {
  at: right of #vitalCardHeart offset 32px;
  size: 432px 220px;
  fill: >panelBg;
  stroke: >spo2Cyan;
  stroke-width: 1px;
  radius: 8px;
}

text #spo2Label {
  at: top left of #vitalCardSpo2 offset 20px 16px;
  content: "OXYGEN SATURATION // SpO2";
  font-size: 12px;
  font-weight: 700;
  color: >spo2Cyan;
}

text #spo2Value {
  at: below #spo2Label offset 8px;
  content: "99";
  font-size: 64px;
  font-weight: 800;
  color: >spo2Cyan;
}

text #spo2Unit {
  at: right of #spo2Value offset 16px;
  content: "%";
  font-size: 24px;
  font-weight: 600;
  color: >textMuted;
}
